window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b2980f9171df920"]={"versions": [{"id": "FIG-8b2980f9171df920", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Konfigurationsarchitektur (ECU Configuration Parameter Definition, ECUC) des BSW-Moduls <code>J1939Nm</code> (SAE J1939 Network Management) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die hierarchische Strukturierung des Moduls in Konfigurationscontainer, Subcontainer, Parameter und Referenzen auf externe BSW-Module (Diagnostic Event Manager, Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul ist definiert über <code>J1939Nm : EcucModuleDef</code> (Multiplizität 0..1) mit drei Hauptcontainern (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>J1939NmGeneral : EcucParamConfContainerDef</code> (Multiplizität 1..1) aggregiert allgemeine Parameter (<code>+parameter</code>):</li>\n<li><code>J1939NmDevErrorDetect : EcucBooleanParamDef</code></li>\n<li><code>J1939NmVersionInfoApi : EcucBooleanParamDef</code></li>\n<li><code>J1939NmMainFunctionPeriod : EcucFloatParamDef</code> (<code>min = 0.001</code>, <code>max = 0.255</code>)</li>\n<li><code>J1939NmTxConfirmationTimeout : EcucFloatParamDef</code> (<code>min = 0</code>, <code>max = 65.535</code>)</li>\n<li><code>J1939NmUserCallout : EcucFunctionNameDef</code> (Multiplizität 0..1)</li>\n<li><code>J1939NmUserCalloutHeaderFile : EcucStringParamDef</code> (Multiplizität 0..1)</li>\n<li><code>J1939NmBusOffDelayTickPeriod : EcucFloatParamDef</code> (<code>min = 0.001</code>, <code>max = 0.255</code>, <code>defaultValue = 0.02</code>, Multiplizität 0..1)</li>\n<li><code>J1939NmConfigSet : EcucParamConfContainerDef</code> (<code>multipleConfigurationContainer = true</code>) aggregiert Subcontainer (<code>+subContainer</code>):</li>\n<li><code>J1939NmChannel : EcucParamConfContainerDef</code> (Multiplizität 1..*, <code>postBuildChangeable = true</code>)</li>\n<li><code>J1939NmNode : EcucParamConfContainerDef</code> (Multiplizität 1..*, <code>postBuildChangeable = true</code>)</li>\n<li><code>J1939NmDemEventParameterRefs : EcucParamConfContainerDef</code> (Multiplizität 0..1) enthält die symbolische Referenz (<code>+reference</code>):</li>\n<li><code>J1939NM_E_ADDRESS_LOST : EcucSymbolicNameReferenceDef</code> (Multiplizität 1..1), verweist via <code>+destination</code> auf <code>DemEventParameter : EcucParamConfContainerDef</code> (Multiplizität 1..65535, <code>(from Dem)</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandssequenzen. Die Parameter steuern zyklische und zeitgesteuerte Abläufe: <code>J1939NmMainFunctionPeriod</code> definiert die Zykluszeit des periodischen Schedulings von <code>J1939Nm_MainFunction</code>, <code>J1939NmTxConfirmationTimeout</code> überwacht Sendeübertragungsbestätigungen, <code>J1939NmBusOffDelayTickPeriod</code> regelt die Verzögerung nach Bus-Off-Ereignissen, und <code>J1939NM_E_ADDRESS_LOST</code> definiert das Diagnose-Event bei Adressverlust im J1939-Netzwerk.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsmetamodell für Modulgeneratoren und Konfigurationswerkzeuge (BSW-Implementierung):</p>\n<ul class=\"fig-list\">\n<li><code>J1939NmConfigSet</code> unterstützt als <code>multipleConfigurationContainer = true</code> multiple Konfigurationssätze (Post-Build-Selektion).</li>\n<li><code>J1939NmChannel</code> und <code>J1939NmNode</code> sind als <code>postBuildChangeable = true</code> gekennzeichnet, womit Kanal- und Knoteneinstellungen zur Post-Build-Laufzeit veränderbar sind.</li>\n<li>Pflichtcontainer <code>J1939NmGeneral</code> erfordert zwingende Festlegung der Periodendauern und Timeouts ohne vorgegebene Defaults für <code>J1939NmMainFunctionPeriod</code> und <code>J1939NmTxConfirmationTimeout</code>.</li>\n<li>Fehlerbehandlung erfordert optionale Verknüpfung der symbolischen Referenz <code>J1939NM_E_ADDRESS_LOST</code> mit einem Dem-Ereignis zur Signalisierung verlorener Adressen.</li>\n</ul>"}, {"id": "FIG-4c77a547adc13d2b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Konfigurationsarchitektur (ECU Configuration Parameter Definition, ECUC) des BSW-Moduls <code>J1939Nm</code> (SAE J1939 Network Management) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die hierarchische Strukturierung des Moduls in Konfigurationscontainer, Subcontainer, Parameter und Referenzen auf externe BSW-Module (Diagnostic Event Manager, Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul ist definiert über <code>J1939Nm : EcucModuleDef</code> (Multiplizität 0..1) mit drei Hauptcontainern (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>J1939NmGeneral : EcucParamConfContainerDef</code> (Multiplizität 1..1) aggregiert allgemeine Parameter (<code>+parameter</code>):</li>\n<li><code>J1939NmDevErrorDetect : EcucBooleanParamDef</code></li>\n<li><code>J1939NmVersionInfoApi : EcucBooleanParamDef</code></li>\n<li><code>J1939NmMainFunctionPeriod : EcucFloatParamDef</code> (<code>min = 0.001</code>, <code>max = 0.255</code>, <code>defaultValue = 0.01</code>)</li>\n<li><code>J1939NmTxConfirmationTimeout : EcucFloatParamDef</code> (<code>min = 0</code>, <code>max = 65.535</code>, <code>defaultValue = 1.5</code>)</li>\n<li><code>J1939NmUserCallout : EcucFunctionNameDef</code> (Multiplizität 0..1)</li>\n<li><code>J1939NmUserCalloutHeaderFile : EcucStringParamDef</code> (Multiplizität 0..1)</li>\n<li><code>J1939NmBusOffDelayTickPeriod : EcucFloatParamDef</code> (<code>min = 0.001</code>, <code>max = 0.255</code>, <code>defaultValue = 0.02</code>, Multiplizität 0..1)</li>\n<li><code>J1939NmConfigSet : EcucParamConfContainerDef</code> aggregiert Subcontainer (<code>+subContainer</code>):</li>\n<li><code>J1939NmChannel : EcucParamConfContainerDef</code> (Multiplizität 1..*)</li>\n<li><code>J1939NmNode : EcucParamConfContainerDef</code> (Multiplizität 1..*)</li>\n<li><code>J1939NmDemEventParameterRefs : EcucParamConfContainerDef</code> (Multiplizität 0..1) enthält die symbolische Referenz (<code>+reference</code>):</li>\n<li><code>J1939NM_E_ADDRESS_LOST : EcucSymbolicNameReferenceDef</code> (Multiplizität 1..1), verweist via <code>+destination</code> auf <code>DemEventParameter : EcucParamConfContainerDef</code> (Multiplizität 1..65535, <code>(from Dem)</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Zustandssequenzen. Die Parameter steuern zyklische und zeitgesteuerte Abläufe: <code>J1939NmMainFunctionPeriod</code> definiert die Zykluszeit des periodischen Schedulings von <code>J1939Nm_MainFunction</code>, <code>J1939NmTxConfirmationTimeout</code> überwacht Sendeübertragungsbestätigungen, <code>J1939NmBusOffDelayTickPeriod</code> regelt die Verzögerung nach Bus-Off-Ereignissen, und <code>J1939NM_E_ADDRESS_LOST</code> definiert das Diagnose-Event bei Adressverlust im J1939-Netzwerk.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsmetamodell für Modulgeneratoren und Konfigurationswerkzeuge (BSW-Implementierung):</p>\n<ul class=\"fig-list\">\n<li><code>J1939NmConfigSet</code> definiert die Konfigurationscontainer für Kanäle (<code>J1939NmChannel</code>) und Knoten (<code>J1939NmNode</code>) ohne Auszeichnung als multipler Konfigurationscontainer oder explizite Post-Build-Änderbarkeit.</li>\n<li>Standardwerte sind für <code>J1939NmMainFunctionPeriod</code> (0.01 s) und <code>J1939NmTxConfirmationTimeout</code> (1.5 s) explizit vorgegeben, wodurch Default-Werte für zyklische Ausführung und Sendeüberwachung vorliegen.</li>\n<li>Fehlerbehandlung erfordert optionale Verknüpfung der symbolischen Referenz <code>J1939NM_E_ADDRESS_LOST</code> mit einem Dem-Ereignis zur Signalisierung verlorener Adressen.</li>\n</ul>"}], "trans": [{"from": "FIG-8b2980f9171df920", "to": "FIG-4c77a547adc13d2b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>J1939NmMainFunctionPeriod</code>: Attribut <code>defaultValue = 0.01</code> ergänzt.</li>\n<li>Parameter <code>J1939NmTxConfirmationTimeout</code>: Attribut <code>defaultValue = 1.5</code> ergänzt.</li>\n<li>Container <code>J1939NmConfigSet</code>: Attribut <code>multipleConfigurationContainer = true</code> entfernt.</li>\n<li>Subcontainer <code>J1939NmChannel</code>: Eigenschaft <code>postBuildChangeable = true</code> entfernt.</li>\n<li>Subcontainer <code>J1939NmNode</code>: Eigenschaft <code>postBuildChangeable = true</code> entfernt.</li>\n</ul>"}]};
